from h import *
R=[]
R.append((6954503,{
"es":L("Salteado de pollo básico",
"Un salteado de pollo clásico con una salsa agridulce que cubre el pollo tierno y las verduras crujientes. Es una comida perfecta para entre semana que puede tener lista en menos de 30 minutos.",
"5","1 taza",
["1 libra de pechugas de pollo deshuesadas y sin piel (cortadas en tiras de 1/2 × 1 pulgada)","1 1/2 cucharadas de salsa de soya baja en sodio (dividida)","1 cucharada de vinagre de arroz","1 cucharada más 2 cucharaditas de maicena (dividida)","1 taza de caldo de pollo bajo en sodio (dividido)","2 cucharadas de salsa hoisin","1 cucharadita de sriracha o pasta de chile y ajo","1 cucharada de aceite vegetal (dividida)","3 dientes de ajo (picados)","1 cucharada de jengibre fresco (pelado y rallado)","1 pimiento rojo mediano (sin corazón ni semillas, en rodajas finas)","2 tallos de apio (en rodajas finas)","1 taza de floretes de brócoli"],
["En un tazón mediano, mezcle el pollo con 1 cucharada de la salsa de soya, el vinagre de arroz y 2 cucharaditas de la maicena. Déjelo marinar a temperatura ambiente durante 15 minutos.","En otro tazón, mezcle la 1/2 cucharada restante de soya, la 1 cucharada restante de maicena, 3/4 taza del caldo de pollo, la salsa hoisin y la sriracha. Reserve.","Caliente la mitad del aceite vegetal en un wok grande a fuego alto. Cuando esté caliente, suba el fuego a medio-alto y agregue el pollo. Saltee durante 5 minutos o hasta que el pollo esté bien cocido. (No es necesario revolver el pollo continuamente, ya que se busca que se forme una costra y se dore.) Pase el pollo del wok a un plato y reserve.","Agregue el aceite restante al wok. Añada el ajo y el jengibre y saltee durante 30 segundos. Agregue el pimiento rojo, el apio y el brócoli y saltee durante 30 segundos. Agregue el caldo de pollo restante, tape y cocine al vapor durante 3 minutos.","Agregue el pollo y saltee durante 1 minuto. Añada la salsa y cocine durante 1 minuto, cubriendo el pollo y las verduras con la salsa. Sirva de inmediato."]),
"ar":L("دجاج مقلي سريع بالطريقة الآسيوية",
"دجاج مقلي كلاسيكي بصلصة لاذعة تغطي الدجاج الطري والخضار المقرمشة. وجبة مثالية لأيام الأسبوع يمكنك تقديمها على المائدة في أقل من 30 دقيقة.",
"5","1 كوب",
["1 رطل صدور دجاج منزوعة العظم والجلد (مقطعة إلى شرائح ½ × 1 بوصة)","1½ ملعقة كبيرة صلصة صويا قليلة الصوديوم (مقسمة)","1 ملعقة كبيرة خل الأرز","1 ملعقة كبيرة و2 ملعقة صغيرة نشا الذرة (مقسمة)","1 كوب مرق دجاج قليل الصوديوم (مقسم)","2 ملعقة كبيرة صلصة هويسين","1 ملعقة صغيرة سريراتشا أو معجون الفلفل والثوم","1 ملعقة كبيرة زيت نباتي (مقسمة)","3 فص ثوم (مفروم)","1 ملعقة كبيرة زنجبيل طازج (مقشر ومبشور)","1 حبة فلفل رومي أحمر متوسطة (منزوعة القلب والبذور ومقطعة شرائح رفيعة)","2 ساق كرفس (مقطعة شرائح رفيعة)","1 كوب زهيرات بروكلي"],
["في وعاء متوسط، اخلط الدجاج مع 1 ملعقة كبيرة من صلصة الصويا وخل الأرز و2 ملعقة صغيرة من نشا الذرة. ضعه جانبًا ليتتبل في درجة حرارة الغرفة لمدة 15 دقيقة.","في وعاء آخر، اخلط ½ ملعقة كبيرة المتبقية من الصويا و1 ملعقة كبيرة المتبقية من نشا الذرة و¾ كوب من مرق الدجاج وصلصة الهويسين والسريراتشا. ضعه جانبًا.","سخّن نصف كمية الزيت النباتي في ووك كبير على نار عالية. عندما يسخن، اجعل النار متوسطة إلى عالية وأضف الدجاج. قلّبه بسرعة لمدة 5 دقائق أو حتى ينضج الدجاج تمامًا. (لا حاجة إلى تقليب الدجاج باستمرار، فالمطلوب أن تتكون عليه قشرة ويتحمر.) انقل الدجاج من الووك إلى طبق وضعه جانبًا.","أضف بقية الزيت إلى الووك. أضف الثوم والزنجبيل وقلّب بسرعة لمدة 30 ثانية. أضف الفلفل الأحمر والكرفس والبروكلي وقلّب بسرعة لمدة 30 ثانية. أضف بقية مرق الدجاج وغطِّ واطهِ على البخار 3 دقائق.","أضف الدجاج وقلّب بسرعة لمدة دقيقة واحدة. أضف الصلصة واطهِ دقيقة واحدة مع تغطية الدجاج والخضار بالصلصة. قدّمه فورًا."])}))
R.append((6955115,{
"es":L("Bol tropical de queso cottage con linaza","Información nutricional del bol tropical de queso cottage con linaza","1","1 1/4 tazas",
["1 taza de queso cottage sin grasa","1/2 taza de trozos de piña (en conserva en su propio jugo)","1 cucharada de semillas de linaza enteras"],["Combine los tres ingredientes y sirva."]),
"ar":L("وعاء استوائي بالجبن القريش وبذور الكتان","المعلومات الغذائية للوعاء الاستوائي بالجبن القريش وبذور الكتان","1","1¼ كوب",
["1 كوب جبن قريش (كوتيج) خالٍ من الدسم","½ كوب قطع أناناس (معلبة في عصيرها الطبيعي)","1 ملعقة كبيرة بذور كتان كاملة"],["اخلط المكونات الثلاثة وقدّمها."])}))
R.append((6955418,{
"ar":L("حساء الكرنب الأجعد بالديك الرومي والفاصوليا",
"الكرنب الأجعد (كيل) من الأغذية الخارقة التي يجب أن تجربها إن لم تكن قد فعلت. وهو مصدر ممتاز لمضادات الأكسدة فيتامينات A وC وK. كما أنه مصدر جيد للبوتاسيوم والألياف، وفي الوقت نفسه منخفض الكربوهيدرات والسعرات الحرارية.",
"7","نحو 1 كوب",
["2 ملعقة صغيرة زيت الكانولا","1 بصلة متوسطة (مقطعة مكعبات)","½ كوب فلفل رومي أخضر (مقطع مكعبات)","1 فص ثوم (مفروم)","6 أونصات ديك رومي مفروم قليل الدهن","32 أونصة مرق دجاج قليل الصوديوم (خالٍ من الغلوتين)","½ كوب طماطم مهروسة معلبة","½ ملعقة صغيرة ريحان (مجفف)","½ ملعقة صغيرة زعتر مجفف","½ ملعقة صغيرة إكليل الجبل مجفف","⅛ ملعقة صغيرة فلفل كايين","1 علبة (15.5 أونصة) لوبيا سوداء العين (مشطوفة ومصفاة)","3 كوب كرنب أجعد (مفروم)","3 ملعقة كبيرة جبن بارميزان (مبشور طازجًا)"],
["سخّن الزيت في قدر حساء كبير على نار متوسطة إلى عالية. أضف البصل والفلفل الأخضر وقلّبها لمدة 3 دقائق أو حتى تصبح شفافة. أضف الثوم وقلّب 30 ثانية.","أضف الديك الرومي واطهِه نحو 8 دقائق حتى يتحمر. أضف بقية المكونات باستثناء جبن البارميزان.","أحضر الحساء إلى الغليان؛ ثم خفّض النار واتركه على نار هادئة 15 دقيقة.","ارفع الحساء عن النار وأضف جبن البارميزان وحرّك."])}))
R.append((6956622,{
"ar":L("لفائف الربيع الصيفية بالدجاج",
"هذه اللفائف لا تحتاج إلى طهي يُذكر، وهي إضافة رائعة إلى أي قائمة طعام صيفية.",
"4","2 لفافة",
["1 كوب ملفوف (مبشور)","1½ كوب دجاج مطبوخ (مقطع خيوطًا)","½ كوب جزر (مبشور)","½ كوب خيار (مقطع مكعبات)","¼ كوب كزبرة خضراء طازجة (مفرومة)","½ كوب فطر شيتاكي (مقطع شرائح رفيعة)","1 ساق بصل أخضر (مفرومة)","8 ورقات أرز لفائف الربيع","2 ملعقة كبيرة صلصة صويا قليلة الصوديوم","3 ملعقة كبيرة خل النبيذ الأرزي","2 ملعقة كبيرة ماء ساخن","1 ملعقة كبيرة زيت زيتون","1 ملعقة صغيرة زنجبيل مطحون"],
["في وعاء متوسط، اخلط الملفوف والدجاج والجزر والخيار والكزبرة الخضراء والفطر والبصل الأخضر.","في وعاء صغير، اخفق صلصة الصويا والخل والماء الساخن وزيت الزيتون والزنجبيل.","قبل الاستخدام، انقع ورقة لفائف الربيع في الماء لمدة 10-15 ثانية ثم انفض عنها الماء الزائد. ضع نحو ⅓ كوب من خليط الدجاج والخضار في الجزء السفلي من الورقة. أمسك حافة الورقة الأقرب إليك واطوِها لتغطية الحشوة. أمسك الحافتين الجانبيتين واطوِهما بإحكام. لفّ إلى الأمام لإغلاق اللفافة. كرر الخطوات مع بقية اللفائف.","قدّم لفائف الربيع مع صلصة الغمس."])}))
R.append((6956653,{
"es":L("Tazas de avena horneada suave con sabor a pastel de calabaza",
"Estas tazas de avena horneada, bajas en grasa y vegetarianas, son un desayuno práctico que se puede preparar con anticipación y que aporta fibra de la avena, la calabaza y la linaza molida para ayudar a mantener estables los niveles de glucosa en la sangre (azúcar en la sangre). Elaboradas sin azúcar ni aceite añadidos, son una opción saludable para las personas que controlan la diabetes.",
"4","2 tazas por porción",
["1 1/2 tazas de avena en hojuelas tradicional","1 cucharada de linaza molida","1/2 cucharadita de canela molida","1/2 cucharadita de polvo de hornear","1/4 cucharadita de nuez moscada molida","1/4 cucharadita de sal","3/4 taza de calabaza enlatada","1 huevo grande","2 cucharadas de yogur griego natural sin grasa","1 taza de leche de almendra sin azúcar (u otra leche baja en grasa)","1 cucharadita de extracto de vainilla"],
["Precaliente el horno a 350 grados F. Forre un molde para magdalenas con 8 capacillos de papel o rocíelo ligeramente con aceite en aerosol antiadherente.","En un tazón grande, combine los ingredientes secos: la avena, la linaza, la canela, el polvo de hornear, la nuez moscada y la sal.","En otro tazón, bata la calabaza, el huevo, el yogur, la leche de almendra y la vainilla.","Agregue la mezcla húmeda a los ingredientes secos y revuelva hasta que estén bien combinados. Déjela reposar 5 minutos para que espese un poco.","Con una cuchara, distribuya la mezcla de manera uniforme en los 8 moldecitos.","Hornee de 25 a 28 minutos, o hasta que cuaje y esté ligeramente dorada por encima.","Deje enfriar 5 minutos antes de sacar del molde. Sirva tibio o guarde en el refrigerador hasta por 5 días."]),
"ar":L("أكواب الشوفان المخبوز الطري بنكهة فطيرة القرع اليقطيني",
"أكواب الشوفان المخبوز هذه قليلة الدسم ونباتية، وهي إفطار عملي يمكن تحضيره مسبقًا، وغنية بالألياف من الشوفان والقرع اليقطيني وبذور الكتان المطحونة للمساعدة على استقرار مستويات الغلوكوز في الدم (سكر الدم). تُحضَّر بدون سكر أو زيت مضاف، وهي خيار صحي لمن يديرون مرض السكري.",
"4","2 كوب لكل حصة",
["1½ كوب شوفان مجروش تقليدي","1 ملعقة كبيرة بذور كتان مطحونة","½ ملعقة صغيرة قرفة مطحونة","½ ملعقة صغيرة بيكنج باودر","¼ ملعقة صغيرة جوزة الطيب المطحونة","¼ ملعقة صغيرة ملح","¾ كوب قرع يقطيني معلب","1 بيضة كبيرة","2 ملعقة كبيرة زبادي يوناني سادة خالٍ من الدسم","1 كوب حليب اللوز غير المحلى (أو حليب آخر قليل الدسم)","1 ملعقة صغيرة مستخلص الفانيليا"],
["سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175 درجة مئوية). بطّن قالب المافن بـ 8 كؤوس ورقية أو ادهنه برفق ببخاخ الطهي غير اللاصق.","في وعاء كبير، اخلط المكونات الجافة: الشوفان وبذور الكتان والقرفة والبيكنج باودر وجوزة الطيب والملح.","في وعاء منفصل، اخفق القرع اليقطيني والبيض والزبادي وحليب اللوز والفانيليا.","أضف الخليط السائل إلى المكونات الجافة وحرّك حتى يمتزج تمامًا. اتركه 5 دقائق ليتكاثف قليلًا.","وزّع الخليط بالملعقة بالتساوي في 8 كؤوس مافن.","اخبز من 25 إلى 28 دقيقة، أو حتى يتماسك ويصبح لونه ذهبيًا فاتحًا من الأعلى.","اتركها تبرد 5 دقائق قبل إخراجها من القالب. قدّمها دافئة أو احفظها في الثلاجة حتى 5 أيام."])}))
R.append((6956969,{
"ar":L("شرائح البيتا المقرمشة بالثوم",
"رقائق البيتا هذه سهلة الحمل أثناء التنقل ويمكن تناولها مع قليل من الحمص أو الغواكامولي أو الصلصة.",
"16","6 مثلثات",
["2 ملعقة كبيرة مسحوق الثوم","1 بخة، 0.25 غرام بخاخ طهي زيت نباتي غير لاصق","6 أرغفة بيتا من القمح الكامل (6 بوصات)"],
["سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175 درجة مئوية). قطّع كل رغيف بيتا إلى 8 أجزاء متساوية. افصل كل جزء إلى قطعتين.","رشّ جانبي قطع البيتا برفق ببخاخ الزيت النباتي غير اللاصق وضعها في طبقة واحدة على صواني خبز كبيرة ذات حواف؛ وانثر عليها مسحوق الثوم. اخبزها 15 دقيقة، أو حتى تصبح ذهبية ومقرمشة.","اترك الرقائق لتبرد؛ قدّمها فورًا أو احفظها في وعاء محكم الإغلاق حتى وقت الاستخدام."])}))
R.append((6957182,{
"ar":L("كونغري خفيف (فاصوليا سوداء وأرز على الطريقة الكوبية)",
"هذه الوصفة الكوبية الكلاسيكية الصحية طبق رائع لإحضاره إلى الحفلات أو لإضافته كطبق جانبي لتكوين وجبة متكاملة.",
"10","¾ كوب",
["10 أونصات فاصوليا سوداء (مجففة، منقاة ومغسولة (1½ كوب))","4 كوب ماء (مقسم (استخدم المزيد عند الحاجة))","½ كوب أرز بني غير مطبوخ","1 ملعقة صغيرة ملح بحري","1½ ملعقة صغيرة زيت الأفوكادو (مقسم)","1 ملعقة صغيرة مسحوق الثوم","1 كوب فلفل أخضر (مفروم ناعمًا)","½ كوب فلفل أحمر (مفروم ناعمًا)","1 كوب بصل إسباني (مفروم ناعمًا)","2 ملعقة كبيرة ثوم (مفروم ناعمًا)","1½ ملعقة كبيرة أوريجانو مجفف (مجفف)","1½ ملعقة صغيرة كمون مطحون","3 ورقات غار (مجففة)"],
["ضع الفاصوليا المغسولة و3 أكواب ماء في قدر ضغط على الموقد وأغلقه. ضع قدر الضغط على الموقد على نار عالية. عندما تبدأ الفاصوليا بالغليان، خفّض النار إلى متوسطة واطهِ الفاصوليا حتى تلين، نحو 45 دقيقة. تأكد من أن الفاصوليا مغمورة بالماء أثناء الطهي؛ وأضف المزيد من الماء عند الحاجة.","عندما تلين الفاصوليا، أضف الأرز و1 كوب ماء والملح و½ ملعقة صغيرة زيت الأفوكادو. حرّك جيدًا وأضف بقية المكونات. حرّك مرة أخرى بالملعقة، وبكل همّة.","تأكد من وجود نحو ¾ بوصة من الماء فوق الفاصوليا. غطِّ الخليط وخفّض النار إلى متوسطة منخفضة. اطهِ 15 دقيقة، أو حتى يلين الأرز. عندما يجهز الكونغري، فكّ حبات الأرز بالشوكة وقدّمه. بالهناء والعافية!"])}))
R.append((6957718,{
"es":L("Ensalada de farro con hierbas y corazones de alcachofa",
"El farro, con su sabor a nuez, se combina con hierbas aromáticas y tiernos corazones de alcachofa para crear una ensalada sabrosa y satisfactoria que celebra los ingredientes saludables. Aliñada con un aderezo ligero, esta ensalada le invita a disfrutar de una mezcla de texturas y sabores, y es una deliciosa adición a su repertorio de recetas aptas para personas con diabetes.",
"6","3/4 taza",
["1 taza de farro (cocido y enfriado)","1 taza de corazones de alcachofa (congelados, en cuartos, descongelados)","1/2 taza de tomates cherry (partidos por la mitad)","1/4 taza de perejil fresco (picado)","1/4 taza de menta fresca (picada)","1/4 taza de queso feta (desmenuzado)","2 cucharadas de aceite de oliva extra virgen","1 cucharada de vinagre de vino tinto","1 diente de ajo (picado)","1/4 cucharadita de pimienta negra","1 limón mediano (cortado en gajos, para servir)"],
["En un tazón grande, combine el farro cocido y enfriado, los corazones de alcachofa en cuartos, los tomates cherry partidos por la mitad, el perejil fresco picado, la menta fresca picada y el queso feta desmenuzado.","En un tazón pequeño, bata el aceite de oliva extra virgen, el vinagre de vino tinto, el ajo picado y la pimienta negra.","Vierta el aderezo sobre la ensalada y mezcle con suavidad para cubrirla de manera uniforme.","Agregue un chorrito de jugo de limón fresco por encima, si lo desea."]),
"ar":L("سلطة الفارو بالأعشاب وقلوب الخرشوف",
"يمتزج الفارو ذو النكهة الجوزية مع الأعشاب العطرية وقلوب الخرشوف الطرية لتحصل على سلطة لذيذة ومشبعة تحتفي بالمكونات الصحية. تُتبَّل بصلصة خفيفة، وتدعوك هذه السلطة للاستمتاع بتشكيلة من القوامات والنكهات، لتكون إضافة لذيذة إلى مجموعة وصفاتك المناسبة لمرضى السكري.",
"6","¾ كوب",
["1 كوب فارو (مطبوخ ومبرد)","1 كوب قلوب الخرشوف (مجمدة، مقطعة أرباعًا، مذابة)","½ كوب طماطم كرزية (مقطعة إلى نصفين)","¼ كوب بقدونس طازج (مفروم)","¼ كوب نعناع طازج (مفروم)","¼ كوب جبن فيتا (مفتت)","2 ملعقة كبيرة زيت زيتون بكر ممتاز","1 ملعقة كبيرة خل النبيذ الأحمر","1 فص ثوم (مفروم)","¼ ملعقة صغيرة فلفل أسود","1 ليمونة متوسطة (مقطعة إلى أرباع، للتقديم)"],
["في وعاء كبير، اخلط الفارو المطبوخ والمبرد وقلوب الخرشوف المقطعة أرباعًا والطماطم الكرزية المقطعة إلى نصفين والبقدونس الطازج المفروم والنعناع الطازج المفروم والجبن الفيتا المفتت.","في وعاء صغير، اخفق زيت الزيتون البكر الممتاز وخل النبيذ الأحمر والثوم المفروم والفلفل الأسود.","اسكب الصلصة فوق السلطة وقلّب برفق لتتغطى بالتساوي.","أضف عصرة من عصير الليمون الطازج فوقها إن رغبت."])}))
R.append((6959709,{
"es":L("Brochetas de tofu a la plancha",
"La autora Jackie Newgent dice: «Si busca una introducción al tofu, conozca estas brochetas estilo Sichuan. Son una forma sabrosa de probar el tofu por primera vez, ¡o por la vez número 101! Marinadas en una vinagreta con jengibre, ensartadas en brochetas, asadas hasta que se forman hermosas marcas caramelizadas de la parrilla y decoradas con hojas frescas de cilantro y semillas de ajonjolí, estas «paletas» de tofu serán un éxito para todos los sentidos. ¡Pruébelas en su próxima comida en casa… o en su próxima parrillada!»",
"6","3 brochetas cada una",
["2 cucharadas de salsa de soya (fermentada naturalmente)","1 1/2 cucharadas de vinagre de arroz (integral)","1 tallo de cebollín (partes verde y blanca, picado finamente)","1 cucharada de jengibre fresco (recién rallado)","1 cucharada de salsa de manzana y chabacano o compota de manzana (sin azúcar añadida)","2 cucharaditas de aceite de ajonjolí (tostado)","1/4 cucharadita de hojuelas de chile rojo triturado (secas)","14 onzas de tofu extra firme (escurrido y exprimido para quitar el exceso de líquido)","1 cucharadita de semillas de ajonjolí negras o blancas (o una mezcla) (tostadas)","2 cucharadas de cilantro fresco"],
["Bata la salsa de soya, el vinagre, el cebollín, el jengibre, la salsa de manzana y chabacano, el aceite de ajonjolí y las hojuelas de chile en un tazón pequeño. (Rinde 1/2 taza). Vierta en un molde de 9 × 13 pulgadas o un recipiente de tamaño similar.","Corte el tofu a lo largo en 9 rebanadas; luego corte cada rebanada por la mitad a lo largo o a lo ancho para obtener 18 piezas. Coloque las rebanadas de tofu en una sola capa en la mezcla de salsa de soya y déjelas marinar de 10 a 15 minutos por lado.","Precaliente una sartén parrilla a fuego medio-alto. Pase cada rebanada de tofu a la sartén con unas pinzas, reservando la marinada. Ase (por tandas) hasta que se formen marcas profundas de la parrilla en ambos lados, unos 3 1/2 a 4 minutos por lado.","Inserte brochetas reutilizables o de bambú en el tofu cocido, espolvoree con las semillas de ajonjolí y las hojas de cilantro, y sirva tibio con el resto de la marinada a un lado."]),
"ar":L("أسياخ التوفو المشوية على المقلاة",
"تقول المؤلفة جاكي نيوجنت: «إذا كنت تبحث عن مدخل إلى عالم التوفو، فتعرّف على أسياخ سيتشوان هذه. إنها طريقة لذيذة لتجربة التوفو للمرة الأولى، أو للمرة الـ 101! تُنقع في صلصة خل بالزنجبيل، وتُغرز في الأسياخ، وتُشوى حتى تتكون عليها علامات شواء كراميلية جميلة، وتُزيَّن بأوراق الكزبرة الخضراء الطازجة وبذور السمسم، لتكون هذه «المصاصات» من التوفو محط إعجاب كل الحواس. جرّبها في وجبتك المنزلية القادمة... أو في رحلة الشواء!»",
"6","3 أسياخ لكل حصة",
["2 ملعقة كبيرة صلصة صويا (مخمرة طبيعيًا)","1½ ملعقة كبيرة خل الأرز (بني)","1 ساق بصل أخضر (الجزء الأخضر والأبيض، مفروم ناعمًا)","1 ملعقة كبيرة زنجبيل طازج (مبشور طازجًا)","1 ملعقة كبيرة صلصة التفاح والمشمش أو هريس التفاح (بدون سكر مضاف)","2 ملعقة صغيرة زيت سمسم (محمص)","¼ ملعقة صغيرة رقائق الفلفل الأحمر المجروشة (مجففة)","14 أونصة توفو شديد التماسك (مصفى ومعصور لإزالة السائل الزائد)","1 ملعقة صغيرة بذور سمسم أسود أو أبيض (أو مزيج منهما) (محمصة)","2 ملعقة كبيرة كزبرة خضراء طازجة"],
["اخفق صلصة الصويا والخل والبصل الأخضر والزنجبيل وصلصة التفاح والمشمش وزيت السمسم ورقائق الفلفل الحار في وعاء صغير. (تعطي ½ كوب). اسكبها في طبق مقاس 9 × 13 بوصة أو طبق مماثل الحجم.","قطّع التوفو بالطول إلى 9 شرائح؛ ثم اقطع كل شريحة إلى نصفين بالطول أو بالعرض للحصول على 18 قطعة. ضع شرائح التوفو في طبقة واحدة في خليط صلصة الصويا واتركها تتتبل من 10 إلى 15 دقيقة لكل جانب.","سخّن مقلاة الشواء مسبقًا على نار متوسطة إلى عالية. انقل كل شريحة توفو إلى المقلاة باستخدام ملقط، مع الاحتفاظ بالتتبيلة. اشوِ (على دفعات) حتى تتكون علامات شواء عميقة على الجانبين، نحو 3½ إلى 4 دقائق لكل جانب.","اغرز أسياخًا قابلة لإعادة الاستخدام أو من الخيزران في التوفو المطبوخ، وانثر عليه بذور السمسم وأوراق الكزبرة الخضراء، وقدّمه دافئًا مع بقية التتبيلة بجانبه."])}))
R.append((6960040,{
"es":L("Bacalao asado con hierbas y verduras de verano asadas sobre quinoa",
"El bacalao es un pescado blanco de sabor suave que adquiere los sabores con los que se cocina. Esta mezcla de especias intensa aporta un sabor mediterráneo y picante al pescado y a las verduras. Disfrútelo con quinoa u otro cereal integral como acompañamiento. Esta receta se puede duplicar fácilmente para alimentar a toda la familia.",
"2","1/3 taza de quinoa + 1 taza de verduras + 6 onzas de bacalao",
["1 taza de tomates uva","1 calabacita amarilla mediana (cortada en rodajas de 1 pulgada)","1 calabacita mediana (cortada en rodajas de 1 pulgada)","1/2 cebolla Vidalia pequeña (en rodajas)","2 dientes de ajo (picados)","2 cucharadas de nueces de Castilla (picadas)","1 cucharada de aceite de oliva extra virgen (dividida)","1 cucharadita de albahaca seca","1/2 cucharadita de orégano seco","1/2 cucharadita de perejil seco","1/4 cucharadita de hojuelas de pimiento rojo triturado","1/4 cucharadita de pimienta negra","2 filetes de bacalao enteros (6 onzas cada uno)","1/3 taza de quinoa (seca)","2/3 taza de agua"],
["Precaliente el horno a 400 grados F. Forre una bandeja para hornear con papel aluminio o papel pergamino.","Coloque los tomates, la calabacita amarilla, la calabacita, la cebolla, los dientes de ajo y las nueces en un tazón grande.","En un tazón pequeño, mezcle el aceite de oliva, la albahaca, el orégano, el perejil, el pimiento rojo y la pimienta negra.","Agregue 2 cucharaditas del aceite de oliva y 2 cucharaditas de la mezcla de especias a las verduras y revuelva para cubrirlas.","Divida la última cucharadita de aceite de oliva y la última cucharadita de la mezcla de especias entre los filetes de bacalao y extiéndalas por encima.","Coloque el bacalao en un extremo de la bandeja y extienda las verduras en el otro extremo. Ase en el horno hasta que el bacalao alcance una temperatura interna de 145 grados F o hasta que el pescado se separe fácilmente con un tenedor y ya no sea translúcido, unos 20 minutos.","Mientras se asan el bacalao y las verduras, prepare la quinoa según las instrucciones del paquete."]),
"ar":L("سمك القد المشوي بالأعشاب مع خضار الصيف المشوية فوق الكينوا",
"سمك القد سمك أبيض خفيف النكهة يكتسب نكهات ما يُطهى معه. يضيف مزيج التوابل الجريء هذا نكهة متوسطية حارة إلى السمك والخضار. استمتع به مع طبق جانبي من الكينوا أو حبوب كاملة أخرى. يمكن مضاعفة هذه الوصفة بسهولة لتكفي العائلة كلها.",
"2","⅓ كوب كينوا + 1 كوب خضار + 6 أونصات سمك قد",
["1 كوب طماطم عنبية","1 حبة كوسا صفراء متوسطة (مقطعة إلى دوائر بسماكة 1 بوصة)","1 حبة كوسا متوسطة (مقطعة إلى دوائر بسماكة 1 بوصة)","½ بصلة فيدالية صغيرة (مقطعة شرائح)","2 فص ثوم (مفروم)","2 ملعقة كبيرة جوز (مفروم)","1 ملعقة كبيرة زيت زيتون بكر ممتاز (مقسمة)","1 ملعقة صغيرة ريحان مجفف","½ ملعقة صغيرة أوريجانو مجفف","½ ملعقة صغيرة بقدونس مجفف","¼ ملعقة صغيرة رقائق الفلفل الأحمر المجروشة","¼ ملعقة صغيرة فلفل أسود","2 شريحة سمك قد (6 أونصات لكل شريحة)","⅓ كوب كينوا (جافة)","⅔ كوب ماء"],
["سخّن الفرن مسبقًا على 400 درجة فهرنهايت (200 درجة مئوية). بطّن صينية خبز بورق ألمنيوم أو ورق زبدة.","ضع الطماطم والكوسا الصفراء والكوسا والبصل وفصوص الثوم والجوز في وعاء كبير.","في وعاء صغير، اخلط زيت الزيتون والريحان والأوريجانو والبقدونس والفلفل الأحمر والفلفل الأسود.","أضف 2 ملعقة صغيرة من زيت الزيتون و2 ملعقة صغيرة من مزيج التوابل إلى الخضار وقلّب لتتغطى.","قسّم الملعقة الصغيرة الأخيرة من زيت الزيتون والملعقة الصغيرة الأخيرة من مزيج التوابل بين شريحتي سمك القد وافردهما على السطح.","ضع سمك القد على أحد طرفي الصينية وافرد الخضار على الطرف الآخر. اشوِ في الفرن حتى تصل درجة الحرارة الداخلية للسمك إلى 145 درجة فهرنهايت (65 درجة مئوية) أو حتى يتفتت السمك بسهولة بالشوكة ولا يعود شفافًا، نحو 20 دقيقة.","بينما يُشوى السمك والخضار، حضّر الكينوا حسب إرشادات العبوة."])}))
R.append((6960253,{
"es":L("Edamame crujiente con limón y hierbas",
"Este refrescante y crujiente refrigerio combina edamame tierno con un chorrito de limón, hierbas frescas aromáticas y un toque de riqueza de las nueces de la India. Es un bocado rápido, sin cocción, que ofrece textura, frescura y satisfacción de origen vegetal en cada cucharada; perfecto para un refrigerio ligero y energizante o una guarnición sencilla.",
"1","1/2 taza",
["1/2 taza de edamame (cocido al vapor y sin vaina)","1 cucharadita de jugo de limón","1/2 cucharadita de hierbas frescas","1/2 onza de nueces de la India"],
["Coloque el edamame cocido al vapor en un tazón pequeño.","Agregue un chorrito de jugo de limón y espolvoree con las hierbas frescas de su elección.","Mezcle con suavidad para combinar.","Cubra con las nueces de la India.","Sirva de inmediato."]),
"ar":L("إدامامي مقرمش بالليمون والأعشاب",
"وجبة خفيفة منعشة ومقرمشة تمزج الإدامامي الطري مع رشة من الليمون والأعشاب الطازجة العطرية ولمسة من الغنى من الكاجو. إنها لقمة سريعة بدون طهي تمنحك القوام والانتعاش والشبع النباتي في كل ملعقة، وهي مثالية كوجبة خفيفة منعشة للطاقة أو كطبق جانبي بسيط.",
"1","½ كوب",
["½ كوب إدامامي (مطهو على البخار ومقشر)","1 ملعقة صغيرة عصير ليمون","½ ملعقة صغيرة أعشاب طازجة","½ أونصة كاجو"],
["ضع الإدامامي المطهو على البخار في وعاء صغير.","أضف عصرة من عصير الليمون وانثر الأعشاب الطازجة التي تختارها.","قلّب برفق للمزج.","زيّنه بالكاجو.","قدّمه فورًا."])}))
R.append((6962321,{
"es":L("Batido de durazno «Peachy Keen»",
"El verano es la temporada alta de los duraznos, lo que convierte a este batido en una gran opción para disfrutar en los días calurosos.",
"2","6 onzas",
["1/2 taza de duraznos congelados","1/2 taza de leche de almendra sin azúcar","1/2 taza de yogur griego natural sin grasa","1 cucharadita de linaza molida","1/2 cucharadita de sustituto de azúcar"],
["Agregue las rodajas de durazno, la leche de almendra, el yogur, la linaza y la miel a una licuadora. Licúe hasta obtener una mezcla suave.","Vierta en dos vasos y disfrute de inmediato."]),
"ar":L("سموذي الخوخ المنعش",
"الصيف هو ذروة موسم الخوخ، مما يجعل هذا السموذي خيارًا رائعًا للاستمتاع به في الأيام الحارة.",
"2","6 أونصات",
["½ كوب خوخ مجمد","½ كوب حليب اللوز غير المحلى","½ كوب زبادي يوناني سادة خالٍ من الدسم","1 ملعقة صغيرة بذور كتان مطحونة","½ ملعقة صغيرة بديل السكر"],
["ضع شرائح الخوخ وحليب اللوز والزبادي وبذور الكتان والعسل في الخلاط. اخلط حتى يصبح ناعمًا.","اسكبه في كوبين واستمتع به فورًا."])}))
save("out_c25_part3.json",R)
